using System;using System.IO;using System.Windows.Forms;namespace Bai4_4_AvatarCSV{public partial class Form1:Form{public Form1(){InitializeComponent();}void btnChonAnh_Click(object s,EventArgs e){OpenFileDialog d=new OpenFileDialog();d.Filter="Image Files|*.jpg;*.jpeg;*.png";if(d.ShowDialog()==DialogResult.OK)pictureAvatar.ImageLocation=d.FileName;}void btnXuatCSV_Click(object s,EventArgs e){SaveFileDialog d=new SaveFileDialog();d.Filter="CSV Files|*.csv";d.FileName="DanhSach.csv";if(d.ShowDialog()==DialogResult.OK){File.WriteAllText(d.FileName,"MaSP,TenSP,DonGia,SoLuong\r\n");MessageBox.Show("Xuất file CSV thành công!");}}}}